# All topic names (for fuzzy matching)
ALL_TOPIC_NAMES = list(TOPIC_CATALOGUE.keys())

def fuzzy_match_topic(query):
    """Return closest matching topic name, or None."""
    q = query.strip().lower()
    for name in ALL_TOPIC_NAMES:
        if q in name.lower() or name.lower() in q: return name
    matches = difflib.get_close_matches(q, [n.lower() for n in ALL_TOPIC_NAMES], n=1, cutoff=0.4)
    if matches:
        for name in ALL_TOPIC_NAMES:
            if name.lower() == matches[0]: return name
    return None

def search_topics(query):
    """Filter topic catalogue by query string."""
    q = query.strip().lower()
    if not q: return ALL_TOPIC_NAMES
    results = []
    for name, data in TOPIC_CATALOGUE.items():
        if q in name.lower(): results.append(name); continue
        if any(q in kw for kw in data.get("keywords", [])): results.append(name); continue
        if any(q in st.lower() for st in data.get("subtopics", [])): results.append(name); continue
    return results

