def _openai_call(prompt, mode="Explain", subtype="Conceptual", history=None):
    key = f"{mode}_{subtype}" if mode == "Explain" else mode
    system = SYSTEM_PROMPTS.get(key, "You are a helpful research assistant.")
    model = AI_MODES[mode]["model"]
    messages = [{"role": "system", "content": system}]
    if history: messages.extend(history)
    messages.append({"role": "user", "content": prompt})
    try:
        client = OpenAI(api_key=OPENAI_KEY)
        resp = client.chat.completions.create(model=model, messages=messages, max_tokens=1800)
        return resp.choices[0].message.content
    except Exception as e:
        return f"ERROR: {e}"

