SOURCE_TYPE_ICONS = {
    "journal": "📖", "magazine": "📰", "news": "📡",
    "repository": "🗄️", "government": "🏛️", "organisation": "🏢",
    "newsletter": "✉️", "website": "🌐", "unknown": "📄",
}

def _make_source(name, source_type, domain, description="", homepage_url="",
                 feed_url="", feed_status="unknown", topics=None):
    """Create a standardised source record."""
    return {
        "name": name, "source_type": source_type, "domain": domain,
        "description": description[:200], "homepage_url": homepage_url,
        "feed_url": feed_url, "feed_status": feed_status,  # "active"|"none"|"unknown"|"restricted"
        "topics": topics or [domain],
        "last_checked": datetime.now().strftime("%Y-%m-%d"),
        "last_refresh": "",
    }

@st.cache_data(ttl=3600, show_spinner=False)
def discover_sources_doaj(domain: str, max_results: int = 20) -> list:
    """Discover academic journals from DOAJ (Directory of Open Access Journals).
    Returns real journal records with metadata — never invented."""
    sources = []
    try:
        q = urllib.parse.quote_plus(domain)
        url = f"https://doaj.org/api/search/journals/{q}?pageSize={max_results}&sort=relevance"
        r = requests.get(url, headers={"User-Agent": "Owlume/1.0"}, timeout=15)
        if r.status_code != 200:
            return []
        data = r.json()
        for item in data.get("results", []):
            bib = item.get("bibjson", {})
            title = bib.get("title", "")
            if not title:
                continue
            subject_list = bib.get("subject", [])
            subjects = [s.get("term", "") for s in subject_list if s.get("term")]
            publisher = bib.get("publisher", {})
            publisher_name = publisher.get("name", "") if isinstance(publisher, dict) else str(publisher)
            desc = f"Publisher: {publisher_name}. Subjects: {', '.join(subjects[:3])}." if subjects else f"Open-access journal. Publisher: {publisher_name}."
            links = bib.get("link", [])
            homepage = next((l.get("url", "") for l in links if l.get("type") == "homepage"), "")
            eissn = bib.get("eissn", "")
            # DOAJ journals don't always have direct RSS — construct standard patterns
            feed_url = f"https://doaj.org/feed" if not eissn else ""
            sources.append(_make_source(
                name=title, source_type="journal", domain=domain,
                description=desc, homepage_url=homepage, feed_url=feed_url,
                feed_status="none" if not feed_url else "unknown", topics=subjects[:4] or [domain]
            ))
        return sources
    except Exception:
        return []

@st.cache_data(ttl=3600, show_spinner=False)
def discover_sources_openalex(domain: str, max_results: int = 15) -> list:
    """Discover journals/venues from OpenAlex sources endpoint."""
    sources = []
    try:
        q = urllib.parse.quote_plus(domain)
        url = (f"https://api.openalex.org/sources?search={q}"
               f"&filter=type:journal&sort=works_count:desc&per-page={max_results}"
               f"&select=display_name,description,homepage_url,type,topics")
        r = requests.get(url, headers={"User-Agent": "Owlume/1.0", "Accept": "application/json"}, timeout=15)
        if r.status_code != 200:
            return []
        data = r.json()
        for item in data.get("results", []):
            name = item.get("display_name", "")
            if not name:
                continue
            desc = item.get("description", "")[:200]
            homepage = item.get("homepage_url", "") or ""
            src_type = item.get("type", "unknown")
            type_map = {"journal": "journal", "repository": "repository", "conference": "organisation",
                        "ebook platform": "website", "book series": "journal"}
            mapped_type = type_map.get(src_type, "website")
            topic_items = item.get("topics", []) or []
            topics_list = [t.get("display_name", "") for t in topic_items[:4] if t.get("display_name")]
            sources.append(_make_source(
                name=name, source_type=mapped_type, domain=domain,
                description=desc, homepage_url=homepage, feed_url="",
                feed_status="none", topics=topics_list or [domain]
            ))
        return sources
    except Exception:
        return []

@st.cache_data(ttl=3600, show_spinner=False)
def discover_sources_gnews_rss(domain: str) -> list:
    """Google News RSS is always a valid universal news source for any domain."""
    q = urllib.parse.quote_plus(domain)
    return [
        _make_source(
            name=f"Google News — {domain}", source_type="news", domain=domain,
            description=f"Latest news articles about {domain} from Google News aggregator.",
            homepage_url="https://news.google.com",
            feed_url=f"https://news.google.com/rss/search?q={q}&hl=en&gl=US&ceid=US:en",
            feed_status="active", topics=[domain]
        ),
    ]

@st.cache_data(ttl=3600, show_spinner=False)
def discover_sources_pubmed(domain: str) -> list:
    """PubMed RSS for health/medicine/biology domains."""
    health_kw = {"health", "medicine", "medical", "clinical", "disease", "biomedical",
                 "epidemiology", "biology", "pharmaceutical", "nursing", "dentistry"}
    if not any(kw in domain.lower() for kw in health_kw):
        return []
    q = urllib.parse.quote_plus(domain)
    return [
        _make_source(
            name="PubMed — NCBI", source_type="repository", domain=domain,
            description="National Library of Medicine database of biomedical literature.",
            homepage_url="https://pubmed.ncbi.nlm.nih.gov",
            feed_url=f"https://pubmed.ncbi.nlm.nih.gov/rss/search/?term={q}&limit=15",
            feed_status="active", topics=[domain, "medicine", "health"]
        ),
    ]

