def _normalize_city(city: str) -> str:
    """Normalise a city name to a registry key."""
    return city.strip().lower()

def _registry_feeds_for(city: str, region: str) -> list:
    """Return all curated feed records for city + region (no duplicates)."""
    city_key = _normalize_city(city)
    region_key = _normalize_city(region) if region else ""
    seen_urls = set()
    feeds = []
    for key in [city_key, region_key]:
        if not key:
            continue
        for rec in _LOCAL_FEED_REGISTRY.get(key, []):
            if rec["url"] not in seen_urls:
                seen_urls.add(rec["url"])
                feeds.append(rec)
    # Always append national fallback (deduped)
    for rec in _LOCAL_FEED_REGISTRY.get("_india_national", []):
        if rec["url"] not in seen_urls:
            seen_urls.add(rec["url"])
            feeds.append(rec)
    return feeds

@st.cache_data(ttl=3600, show_spinner=False)
def discover_local_sources(city: str, region: str = "") -> list:
    """Discover local news sources for a city/region.
    Returns a list of source records — validated active feeds first.
    Uses Google News RSS (always works) + curated registry (validated).
    Results cached 1 h; does NOT run on every Streamlit rerun."""
    if not city.strip():
        return []

    city_s = city.strip()
    region_s = region.strip() if region else ""
    sources: list = []
    seen_urls: set = set()

    # 1. Google News RSS — always works, city-scoped
    city_q = urllib.parse.quote_plus(city_s)
    gnews_city_url = f"https://news.google.com/rss/search?q={city_q}+local+news&hl=en-IN&gl=IN&ceid=IN:en"
    sources.append(_make_source(
        name=f"Google News — {city_s}",
        source_type="news", domain="local",
        description=f"Latest news from {city_s} aggregated by Google News.",
        homepage_url="https://news.google.com",
        feed_url=gnews_city_url,
        feed_status="active",
        topics=[city_s, "local news", "community"],
    ))
    seen_urls.add(gnews_city_url)

    # 2. Google News RSS — region/state scoped (if region provided)
    if region_s:
        region_q = urllib.parse.quote_plus(region_s)
        gnews_region_url = f"https://news.google.com/rss/search?q={region_q}+news&hl=en-IN&gl=IN&ceid=IN:en"
        if gnews_region_url not in seen_urls:
            sources.append(_make_source(
                name=f"Google News — {region_s}",
                source_type="news", domain="local",
                description=f"Latest news from {region_s}.",
                homepage_url="https://news.google.com",
                feed_url=gnews_region_url,
                feed_status="active",
                topics=[region_s, "local news"],
            ))
            seen_urls.add(gnews_region_url)

    # 3. Curated registry feeds
    registry = _registry_feeds_for(city_s, region_s)
    for rec in registry:
        if rec["url"] in seen_urls:
            continue
        # Quick validation — don't add feeds that 404 or return no entries
        try:
            r = requests.get(rec["url"], headers={"User-Agent": "Owlume/1.0"}, timeout=8)
            feed = feedparser.parse(r.content)
            status = "active" if feed.entries else "none"
        except Exception:
            status = "error"
        if status in ("none", "error"):
            continue
        seen_urls.add(rec["url"])
        source_type_map = {"official": "government", "regional": "news", "community": "community"}
        sources.append(_make_source(
            name=rec["name"],
            source_type=source_type_map.get(rec["type"], "news"),
            domain="local",
            description=f"Local news source for {city_s}.",
            homepage_url="",
            feed_url=rec["url"],
            feed_status=status,
            topics=[city_s, "local news", rec["type"]],
        ))

    return sources


@st.cache_data(ttl=1800, show_spinner=False)
def load_local_articles(city: str, region: str, interests_tuple: tuple) -> list:
    """Fetch and rank local articles.  Called only when the Local News tab is open.
    Cached 30 min — does NOT re-run on every Streamlit rerun."""
    if not city.strip():
        return []

    sources = discover_local_sources(city, region)
    all_arts: list = []
    city_lower = city.lower()
    region_lower = region.lower() if region else ""
    interests = list(interests_tuple)

    for src in sources:
        feed_url = src.get("feed_url", "")
        if not feed_url or src.get("feed_status") == "error":
            continue
        arts = _fetch_rss(feed_url, src["name"], "local", max_items=15)
        for art in arts:
            art["local_source_type"] = src.get("source_type", "news")
        all_arts += arts

    # Relevance score: location name in title/summary = strong signal
    for art in all_arts:
        text = (art.get("title", "") + " " + art.get("summary", "")).lower()
        score = 0.0
        if city_lower and city_lower in text:
            score += 0.5
        if region_lower and region_lower in text:
            score += 0.2
        for interest in interests:
            if interest.lower()[:6] in text:
                score += 0.1
        # Penalise articles that seem purely national/global with no local anchor
        national_words = ["india", "government of india", "parliament", "supreme court of india"]
        if not any(w in text for w in [city_lower] + ([region_lower] if region_lower else [])):
            if any(nw in text for nw in national_words):
                score -= 0.1
        art["local_relevance"] = round(min(1.0, max(0.0, score)), 3)

    all_arts = deduplicate_articles(all_arts)
    all_arts.sort(key=lambda a: a.get("local_relevance", 0), reverse=True)
    return all_arts


def validate_rss_feed(url: str) -> str:
    """Attempt to parse a feed URL. Returns 'active', 'none', or 'error'."""
    if not url:
        return "none"
    try:
        r = requests.get(url, headers={"User-Agent": "Owlume/1.0"}, timeout=8)
        feed = feedparser.parse(r.content)
        if feed.entries:
            return "active"
        return "none"
    except Exception:
        return "error"

def discover_sources_for_domain(domain: str) -> list:
    """Run all discovery providers for a domain and merge results.
    Returns a list of source dicts; never invents sources."""
    results = []
    seen_names = set()

    # Always: Google News RSS (universal)
    results += discover_sources_gnews_rss(domain)

    # Academic/scholarly: DOAJ journals
    doaj = discover_sources_doaj(domain, max_results=15)
    results += doaj

    # Academic/scholarly: OpenAlex sources
    oa = discover_sources_openalex(domain, max_results=10)
    results += oa

    # Health domains: PubMed
    results += discover_sources_pubmed(domain)

    # Deduplicate by name (case-insensitive)
    deduped = []
    for src in results:
        key = src["name"].lower().strip()
        if key not in seen_names:
            seen_names.add(key)
            deduped.append(src)

    return deduped

def load_articles_from_followed_sources(topic: str, subtopics=None) -> list:
    """Load articles from sources the user explicitly follows, supplementing the main pipeline."""
    arts = []
    followed = st.session_state.get("followed_sources", set())
    cat = st.session_state.get("source_catalogue", {})
    for feed_url in followed:
        src = cat.get(feed_url, {})
        if src.get("feed_status") == "active" and feed_url.startswith("http"):
            label = src.get("name", "Followed Source")
            arts += _fetch_rss(feed_url, label, topic, max_items=5)
    return arts

# ═══════════════════════════════════════════════════════════
# AI PROMPTS
# ═══════════════════════════════════════════════════════════
def build_explain_prompt(title, url, summary, mode="Explain", subtype="Conceptual"):
    instr = {"Explain": f"Explain this article ({subtype})", "Research": "Deep research analysis",
             "Digest": "Concise digest for busy researchers", "Critical Lens": "Critically analyse",
             "Policy Lens": "Policy implications"}.get(mode, "Explain")
    return f"""{instr}.\nTitle: \"{title}\"\n{f"URL: {url}" if url else ""}\n{f"Snippet: {summary[:400]}" if summary else ""}\n\n## 📌 What Is This?\n## 🕰️ Background\n## 📊 Current Evidence\n## 🔮 What's Next\n## 💡 Why It Matters\n\nEnd with exactly: SUGGESTIONS: q1? | q2? | q3?"""

def build_summary_prompt(title, summary):
    return f"""Write a 3-sentence AI summary of this article for a busy researcher.\nTitle: {title}\nSnippet: {summary[:300]}\nBe factual and precise."""

def build_takeaways_prompt(title, summary):
    return f"""List 4-5 key takeaways from this article as bullet points.\nTitle: {title}\nSnippet: {summary[:300]}\nEach bullet: one clear, specific insight."""

def build_why_matters_prompt(title, summary):
    return f"""In 2-3 sentences, explain WHY this matters — the broader significance, implications, or why a researcher should care.\nTitle: {title}\nSnippet: {summary[:300]}"""

def build_briefing_prompt(articles):
    items = "\n".join([f"- [{a['topic']}] {a['title']}" for a in articles[:30]])
    return f"""Write a personalised research briefing.\nARTICLES:\n{items}\n\n## 🌅 Today's Briefing\n## 🔑 Key Stories\n## 🧩 Emerging Themes\n## 📌 Worth Watching\nTone: concise, research-grade, insightful."""

def parse_explanation(text):
    followups = []
    if "SUGGESTIONS:" in text:
        parts = text.split("SUGGESTIONS:"); text = parts[0].strip()
        followups = [q.strip() for q in parts[1].split("|") if "?" in q][:3]
    sections, label, lines = [], None, []
    for line in text.split("\n"):
        if line.startswith("## "):
            if label: sections.append((label,"\n".join(lines).strip()))
            label, lines = line[3:].strip(), []
        else: lines.append(line)
    if label: sections.append((label,"\n".join(lines).strip()))
    return sections, followups

# ═══════════════════════════════════════════════════════════
# BOOKMARK + LIBRARY HELPERS
# ═══════════════════════════════════════════════════════════
CATEGORIES = ["Read later","Key paper","Clinical relevance","Policy note","Inspiration","Evidence gap"]

def is_bookmarked(url): return any(b["article"]["url"] == url for b in st.session_state.bookmarks)
def add_bookmark(art, cat="Read later"):
    if not is_bookmarked(art["url"]):
        st.session_state.bookmarks.append({"article": art, "category": cat, "saved_at": datetime.now().strftime("%d %b %Y")})
def remove_bookmark(url): st.session_state.bookmarks = [b for b in st.session_state.bookmarks if b["article"]["url"] != url]
def add_to_library(art):
    urls = {a["url"] for a in st.session_state.library}
    if art.get("url") not in urls:
        st.session_state.library.append({"title": art.get("title",""), "url": art.get("url","#"),
            "topic": art.get("topic",""), "summary": art.get("summary","")[:200],
            "ts": datetime.now().strftime("%Y-%m-%d %H:%M")})

def get_tier():
    sub = st.session_state.get("subscription")
    if not sub: return "free"
    if sub.get("status") == "premium": return "premium"
    return "free"

def max_topics():
    return 99 if get_tier() == "premium" else 5

