# HELPERS
# ═══════════════════════════════════════════════════════════
def topic_color(name):
    # Custom topics not in catalogue get a deterministic colour
    if name in TOPIC_CATALOGUE:
        return TOPIC_CATALOGUE[name]["color"]
    colours = ["#7048e8","#2f9e44","#e67700","#c92a2a","#1098ad","#5f3dc4","#087f5b","#a61e4d"]
    return colours[abs(hash(name)) % len(colours)]

def topic_icon(name):
    if name in TOPIC_CATALOGUE:
        return TOPIC_CATALOGUE[name]["icon"]
    # Generic icon for any custom/unknown topic
    generic = ["🔬","🧬","🌐","⚡","🛠","📡","🏛","🌱","⚖️","🎯","🏔","🎓","🔭","🧲","📊"]
    return generic[abs(hash(name)) % len(generic)]

def all_topics_for_user():
    return st.session_state.selected_topics + st.session_state.custom_topics

def check_ai_available():
    try: OpenAI(api_key=OPENAI_KEY); return True, ""
    except: return False, "OpenAI key not configured"

